def decide(recipient_reputation, round_num, my_history):
    # Use personal experience: recent defections by others when I was the recipient
    recent_defections = 0
    total = 0
    # Look at the last 10 rounds (or all available)
    lookback = min(10, len(my_history))
    for entry in my_history[-lookback:]:
        if entry['partner_action'] != 'donate':
            recent_defections += 1
        total += 1
    if total > 0:
        defection_rate = recent_defections / total
        # Threshold adapts: more defections → higher threshold (stricter)
        threshold = -0.5 + defection_rate * 1.0
    else:
        # Start generous with no history
        threshold = -1.0
    # Gradually become stricter over rounds
    threshold += 0.1 * round_num
    return recipient_reputation >= threshold
